def _fr13_write_apc_env_sidecar() -> None:
    """Bridge the FR13_APC_* masters to the mp/spawn EngineCore worker.

    The worker's curated env DROPS the bare FR13_APC_* masters (audit 2026-06-27:
    only FR13_APC_HIT_RECURRENT_SUFFIX + FR13_APC_LEAF_CROSSCHECK survive into the
    worker; SNAP_FIX / SNAP_FIX_ZEROACCEPT / CONV_FIX / CONV_SNAPSHOT / CONV_SNAP_FIX /
    PRE_SNAP_FIX / HIT_SUFFIX_CAP / BLOCK_ALIGN_45477 are all dropped). The os.environ
    gates in the patched gdn file then read DEFAULTS in the worker (cap=64 not 1e6,
    SNAP_FIX off, etc.), making every env-gated APC fix VACUOUS. pid-1 has the full
    env: write the present FR13_APC_* values as key=value lines into a /logs sidecar;
    the patched gdn-file module-load (see _patch_gdn_linear) injects them into the
    worker's os.environ BEFORE any gate reads. No FR13_APC_* set (locked non-APC
    path) -> sidecar removed -> byte-identical.
    """
    import os
    flag_path = os.environ.get("FR13_APC_ENV_FLAG_FILE", "/logs/fr13_apc_env.flag")
    keys = [
        "FR13_APC_SNAP_FIX", "FR13_APC_SNAP_FIX_ZEROACCEPT", "FR13_APC_CONV_FIX",
        "FR13_APC_CONV_SNAPSHOT", "FR13_APC_CONV_SNAP_FIX", "FR13_APC_PRE_SNAP_FIX",
        "FR13_APC_HIT_SUFFIX_CAP", "FR13_APC_BLOCK_ALIGN_45477", "FR13_APC_LEAF_CROSSCHECK",
    ]
    present = [(k, os.environ[k]) for k in keys if k in os.environ]
    try:
        if present:
            os.makedirs(os.path.dirname(flag_path) or ".", exist_ok=True)
            with open(flag_path, "w") as _fh:
                for k, v in present:
                    _fh.write(k + "=" + v + "\n")
            print("FR13_APC env sidecar written (worker-env bridge): " + flag_path
                  + " keys=" + ",".join(k for k, _ in present))
        else:
            try:
                os.remove(flag_path)
            except FileNotFoundError:
                pass
    except Exception as exc:  # pragma: no cover - best-effort, fail-safe-OFF
        print("FR13_APC env sidecar write failed: %s" % exc)




def _patch_single_type_manager_zero_mamba() -> bool:
    """FR13_APC_ZERO_MAMBA_ON_ALLOC (default OFF; PATCH-TIME gated -> when the
    env flag is not "1" at patch time this returns False and the installed
    source stays byte-identical to the pre-edit patcher's output).

    Carrier (FR13_TREECACHE_CAMPAIGN_20260704 sec.47/48, wf_5fda85e5-3c4):
    vLLM zeros freshly-allocated blocks ONLY for full-attention groups. The base
    SingleTypeKVCacheManager records new_block_ids solely when the spec is
    (TQ)FullAttentionSpec (allocate_new_blocks / allocate_new_computed_blocks);
    MambaManager NEVER records its blocks, and vLLM's KVBlockZeroer
    (worker/utils.py init_meta) explicitly SKIPS mamba layers ("Only
    AttentionSpec layers are processed; Mamba layers are skipped"). block_pool
    get_new_blocks pops freed rows with no memset and reset_prefix_cache never
    zeros contents => recycled GDN conv/ssm state-pool rows carry request N-1
    residual into request N's cold prefill (align chunk-carry read
    has_initial_state=True, gdn_linear_attn) and into the tree spec node-bank
    reads => the sec.47 request-order contamination. Request #1 is clean only
    because the model runner zeros everything once at boot.

    Producer-side fix: under the flag, record the block ids MambaManager freshly
    POPS FROM THE POOL -- both the non-align super() path and the align custom
    path, and NEVER the null/reused blocks -- into the manager's new_block_ids so
    they ride the existing take_new_block_ids -> new_block_ids_to_zero channel
    (KVCacheManager.take_new_block_ids already iterates every single_type
    manager; the drain fires each step because needs_kv_cache_zeroing ==
    has_mamba_layers). The CONSUMER side is gpu_model_runner.
    _fr13_zero_mamba_block_ids, which zeros the conv_state/ssm_state ROWS for
    those ids: the generic KVBlockZeroer alone targets the FULL-ATTENTION tensors
    (wrong shape/strides for the mamba conv/ssm pools), so a mamba-specific
    zeroer is required. Because there is ONE shared block pool, any id in the
    drained list is owned by exactly one group, so zeroing that id's row in the
    mamba tensors (free for a full-attn id, owned for a mamba id) is always
    safe. Boot needle + throttled counter prove engagement (class 9)."""
    if os.environ.get("FR13_APC_ZERO_MAMBA_ON_ALLOC", "0") != "1":
        return False
    text = SINGLE_TYPE_MANAGER_PATH.read_text()
    sentinel = "# FR13_APC_ZERO_MAMBA_ON_ALLOC"
    if sentinel in text:
        return False

    mod_anchor = "from vllm.v1.request import Request\n"
    if text.count(mod_anchor) != 1:
        raise RuntimeError(
            "zero_mamba: single_type module import anchor not unique/found"
        )
    mod_inject = mod_anchor + (
        "\n"
        "# FR13_APC_ZERO_MAMBA_ON_ALLOC producer-side recorder. See patcher\n"
        "# _patch_single_type_manager_zero_mamba for the full carrier writeup.\n"
        "import os as _fr13zm_os\n"
        "_FR13_ZM_ON = _fr13zm_os.environ.get("
        "\"FR13_APC_ZERO_MAMBA_ON_ALLOC\", \"1\") != \"0\"\n"
        "_fr13zm_events = 0\n"
        "_fr13zm_blocks = 0\n"
        "\n"
        "\n"
        "def _fr13zm_record(mgr, ids):\n"
        "    if not ids:\n"
        "        return\n"
        "    mgr.new_block_ids.extend(ids)\n"
        "    global _fr13zm_events, _fr13zm_blocks\n"
        "    _fr13zm_events += 1\n"
        "    _fr13zm_blocks += len(ids)\n"
        "    if _fr13zm_events % 100 == 1:\n"
        "        print(\n"
        "            \"FR13_APC_ZERO_MAMBA record engaged: events=\""
        " + str(_fr13zm_events)\n"
        "            + \" cumulative_block_ids=\" + str(_fr13zm_blocks)\n"
        "            + \" last_batch=\" + str(len(ids)),\n"
        "            flush=True,\n"
        "        )\n"
        "\n"
        "\n"
        "if _FR13_ZM_ON:\n"
        "    print(\n"
        "        \"FR13_APC_ZERO_MAMBA boot needle: single_type_kv_cache_manager \"\n"
        "        \"mamba fresh-alloc recording ACTIVE (flag ON at patch time)\",\n"
        "        flush=True,\n"
        "    )\n"
    )
    text = text.replace(mod_anchor, mod_inject, 1)

    nonalign_anchor = (
        "            return super().allocate_new_blocks(\n"
        "                request_id, num_tokens, num_tokens_main_model\n"
        "            )\n"
    )
    if text.count(nonalign_anchor) != 1:
        raise RuntimeError(
            "zero_mamba: MambaManager non-align allocate anchor not unique/found"
        )
    nonalign_inject = (
        "            _fr13zm_new = super().allocate_new_blocks(\n"
        "                request_id, num_tokens, num_tokens_main_model\n"
        "            )\n"
        "            if _FR13_ZM_ON:  " + sentinel + "\n"
        "                _fr13zm_record(self, [b.block_id for b in _fr13zm_new])\n"
        "            return _fr13zm_new\n"
    )
    text = text.replace(nonalign_anchor, nonalign_inject, 1)

    align_anchor = (
        "                new_blocks = self.block_pool.get_new_blocks(num_new_blocks)\n"
        "                req_blocks.extend(new_blocks)\n"
        "                self._allocated_block_reqs.add(request_id)\n"
        "                return req_blocks[prev_block_len:]\n"
    )
    if text.count(align_anchor) != 1:
        raise RuntimeError(
            "zero_mamba: MambaManager align allocate anchor not unique/found"
        )
    align_inject = (
        "                new_blocks = self.block_pool.get_new_blocks(num_new_blocks)\n"
        "                req_blocks.extend(new_blocks)\n"
        "                self._allocated_block_reqs.add(request_id)\n"
        "                if _FR13_ZM_ON:  " + sentinel + "\n"
        "                    _fr13zm_record(self, [b.block_id for b in new_blocks])\n"
        "                return req_blocks[prev_block_len:]\n"
    )
    text = text.replace(align_anchor, align_inject, 1)

    SINGLE_TYPE_MANAGER_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_zero_mamba() -> bool:
    """FR13_APC_ZERO_MAMBA_ON_ALLOC consumer side (PATCH-TIME gated -> no
    injection / byte-identical source when the flag is not "1" at patch time).

    Adds the mamba-specific zeroing that vLLM's KVBlockZeroer (worker/utils.py)
    does NOT do. _zero_block_ids is invoked from _update_states BEFORE the
    forward (execute_model -> _update_states -> _prepare_inputs -> model()), so
    the zero lands ahead of the prefill chunk-carry / tree node-bank read. We
    zero conv_state/ssm_state ROW block_id for every id MambaManager recorded
    into new_block_ids (dim-0 of each mamba state tensor is indexed by block id;
    see _reshape_kv_cache_tensors target_shape=(num_blocks, *shape) and
    gdn_linear_attn ssm_state[non_spec_state_indices_tensor]). Reads the layer
    kv_cache exactly like KVBlockZeroer.init_meta does
    (static_forward_context[layer].kv_cache), filtering MambaSpec groups."""
    if os.environ.get("FR13_APC_ZERO_MAMBA_ON_ALLOC", "0") != "1":
        return False
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_APC_ZERO_MAMBA_ON_ALLOC"
    if sentinel in text:
        return False
    anchor = (
        "    def _zero_block_ids(self, block_ids: list[int]) -> None:\n"
        "        \"\"\"Zero the KV cache memory for the given block IDs.\"\"\"\n"
        "        if hasattr(self, \"_kv_block_zeroer\"):\n"
        "            self._kv_block_zeroer.zero_block_ids(block_ids)\n"
    )
    if text.count(anchor) != 1:
        raise RuntimeError(
            "zero_mamba: gpu_model_runner _zero_block_ids anchor not unique/found"
        )
    inject = anchor + (
        "        self._fr13_zero_mamba_block_ids(block_ids)  " + sentinel + "\n"
        "\n"
        "    def _fr13_zero_mamba_block_ids(self, block_ids) -> None:\n"
        "        " + sentinel + ": KVBlockZeroer (worker/utils.py) only zeros\n"
        "        # FullAttentionSpec tensors; mamba conv_state/ssm_state pool rows\n"
        "        # are never zeroed on (re)alloc, so recycled rows carry request\n"
        "        # N-1 residual into the cold-prefill chunk-carry read\n"
        "        # (gdn_linear_attn has_initial_state=True) and tree node-bank\n"
        "        # reads. Zero those rows, indexed by the fresh mamba block ids\n"
        "        # MambaManager recorded into new_block_ids.\n"
        "        if not block_ids:\n"
        "            return\n"
        "        st = getattr(self, \"_fr13zm_state_tensors\", None)\n"
        "        if st is None:\n"
        "            import os as _fr13zm_os\n"
        "            if _fr13zm_os.environ.get("
        "\"FR13_APC_ZERO_MAMBA_ON_ALLOC\", \"1\") == \"0\":\n"
        "                self._fr13zm_state_tensors = []\n"
        "                self._fr13zm_calls = 0\n"
        "                self._fr13zm_blocks = 0\n"
        "                return\n"
        "            st = []\n"
        "            _sfc = self.compilation_config.static_forward_context\n"
        "            for _grp in self._kv_cache_spec_attn_group_iterator():\n"
        "                if not isinstance(_grp.kv_cache_spec, MambaSpec):\n"
        "                    continue\n"
        "                for _ln in _grp.layer_names:\n"
        "                    _layer = _sfc.get(_ln)\n"
        "                    _kv = getattr(_layer, \"kv_cache\", None)\n"
        "                    if isinstance(_kv, (list, tuple)):\n"
        "                        for _t in _kv:\n"
        "                            if isinstance(_t, torch.Tensor):\n"
        "                                st.append(_t)\n"
        "            self._fr13zm_state_tensors = st\n"
        "            self._fr13zm_calls = 0\n"
        "            self._fr13zm_blocks = 0\n"
        "            print(\n"
        "                \"FR13_APC_ZERO_MAMBA boot needle: gpu_model_runner \"\n"
        "                + \"registered \" + str(len(st))\n"
        "                + \" mamba state tensors for on-alloc zeroing (flag ON)\",\n"
        "                flush=True,\n"
        "            )\n"
        "        if not st:\n"
        "            return\n"
        "        _idx = torch.as_tensor(\n"
        "            block_ids, dtype=torch.long, device=st[0].device\n"
        "        )\n"
        "        for _t in st:\n"
        "            _t[_idx] = 0\n"
        "        self._fr13zm_calls += 1\n"
        "        self._fr13zm_blocks += len(block_ids)\n"
        "        if self._fr13zm_calls % 100 == 1:\n"
        "            print(\n"
        "                \"FR13_APC_ZERO_MAMBA zero engaged: calls=\"\n"
        "                + str(self._fr13zm_calls)\n"
        "                + \" cumulative_block_rows=\" + str(self._fr13zm_blocks)\n"
        "                + \" last_batch=\" + str(len(block_ids)),\n"
        "                flush=True,\n"
        "            )\n"
    )
    text = text.replace(anchor, inject, 1)
    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def _patch_gdn_linear_attn_prefill_carry_trace() -> bool:
    """FR13_APC_PREFILL_CARRY_TRACE (D-E4CAP; default OFF; PATCH-TIME gated ->
    when the env flag is not "1" at patch time this returns False and the
    installed source stays byte-identical to the pre-edit patcher's output).

    Campaign sec.51 (FR13_TREECACHE_CAMPAIGN_20260704): E5 removed the
    ACCUMULATING recycled-pool carrier, leaving ONE deterministic cold-path
    fixed point ('The'@-0.0111) that is E5-invariant (identical pre/post E5) =>
    it is NOT a fresh-alloc pool row. Top suspect = the UNGUARDED chunked-prefill
    SSM carry: initial_state = ssm_state[non_spec_state_indices_tensor] (read),
    zeroed only for ~has_initial_state rows, then the carry WRITE
    ssm_state[non_spec_state_indices_tensor] = last_recurrent_state. ~24.7k
    prompt / max_num_batched=1024 => ~24 chunks, has_initial_state=True at every
    chunk boundary, so a null/stale-row read can feed the prefill accumulation
    deterministically. This tracer is the DECISIVE one-boot discriminator: it
    logs, per prefill forward per layer, the non_spec_state_indices (flag id==0 =
    null row), the AS-READ initial_state per-row fingerprint (BEFORE the zeroing)
    and the written last_recurrent_state per-row fingerprint. Diff
    request-1-vs-2 per chunk: first-divergence at id 0 => S1 null row; at a
    non-fresh non-zero id => S2 stale carry index; identical + no null =>
    recurrent exonerated.

    READ-ONLY: every tensor is .detach()ed, no compute-path tensor is mutated,
    and control flow is UNCHANGED when the flag is off (patch-time gate -> no
    injection at all). The whole trace body is wrapped in try/except so a trace
    failure can NEVER break serving (prints one FR13_CARRY_TRACE_ERROR line then
    self-disables). Volume is bounded by FR13_APC_PREFILL_CARRY_TRACE_LIMIT
    (default 20000 records) and the jsonl path by
    FR13_APC_PREFILL_CARRY_TRACE_PATH. Boot needle + first-record print + a
    line-buffered file prove engagement (class 9). Runs LAST on
    gdn_linear_attn.py, so its anchors match the post-_patch_gdn_linear text
    (the read/zero/write region is heavily rewritten by that patch; raw-image
    anchors do not survive)."""
    if os.environ.get("FR13_APC_PREFILL_CARRY_TRACE", "0") != "1":
        return False
    text = GDN_LINEAR_PATH.read_text()
    sentinel = "# FR13_APC_PREFILL_CARRY_TRACE"
    if sentinel in text:
        return False

    mod_anchor = (
        "_FR10_DECODE_MODE = os.environ.get(\"FR10_DECODE_MODE_DEFAULT\", "
        "\"tree_mtp\")\n"
    )
    if text.count(mod_anchor) != 1:
        raise RuntimeError(
            "carry_trace: gdn_linear module-level anchor not unique/found"
        )
    mod_block = '''

# FR13_APC_PREFILL_CARRY_TRACE (D-E4CAP): READ-ONLY, default-OFF prefill carry
# tracer. See patcher _patch_gdn_linear_attn_prefill_carry_trace for the full
# carrier writeup (campaign sec.51). PATCH-TIME gated: this block is injected
# only when FR13_APC_PREFILL_CARRY_TRACE == "1" at patch time, so OFF => the
# installed source is byte-identical. All tensor reads are .detach()ed; no
# compute-path tensor is mutated.
import json as _fr13pct_json
import os as _fr13pct_os

_FR13PCT_ON = _fr13pct_os.environ.get("FR13_APC_PREFILL_CARRY_TRACE", "1") != "0"
_FR13PCT_PATH = _fr13pct_os.environ.get(
    "FR13_APC_PREFILL_CARRY_TRACE_PATH", "/logs/fr13_prefill_carry_trace.jsonl"
)
try:
    _FR13PCT_LIMIT = int(
        _fr13pct_os.environ.get("FR13_APC_PREFILL_CARRY_TRACE_LIMIT", "20000")
    )
except Exception:
    _FR13PCT_LIMIT = 20000
_fr13pct_seq = 0
_fr13pct_cur_seq = 0
_fr13pct_records = 0
_fr13pct_fh = None
_fr13pct_disabled = False
_fr13pct_cap_printed = False
_fr13pct_first = True


def _fr13pct_open():
    global _fr13pct_fh
    if _fr13pct_fh is None:
        _dirn = _fr13pct_os.path.dirname(_FR13PCT_PATH)
        if _dirn:
            _fr13pct_os.makedirs(_dirn, exist_ok=True)
        _fr13pct_fh = open(_FR13PCT_PATH, "a", buffering=1)
    return _fr13pct_fh


def _fr13pct_rowfp(t):
    # Per-row abs-sum fingerprint == float(row.detach().float().abs().sum()).
    # ONE device sync (single .cpu().tolist()) instead of per-row .item().
    if t is None:
        return None
    f = t.detach().float().abs()
    return [
        float(_x) for _x in f.reshape(f.shape[0], -1).sum(dim=1).cpu().tolist()
    ]


def _fr13pct_emit(rec):
    global _fr13pct_records, _fr13pct_cap_printed, _fr13pct_first
    if _fr13pct_records >= _FR13PCT_LIMIT:
        if not _fr13pct_cap_printed:
            _fr13pct_cap_printed = True
            print(
                "FR13_CARRY_TRACE cap reached: records="
                + str(_fr13pct_records),
                flush=True,
            )
        return
    _fh = _fr13pct_open()
    _fh.write(_fr13pct_json.dumps(rec) + chr(10))
    _fr13pct_records += 1
    if _fr13pct_first:
        _fr13pct_first = False
        print(
            "FR13_CARRY_TRACE first record written: path=" + _FR13PCT_PATH,
            flush=True,
        )


def _fr13pct_common(_seq, mod, attn_metadata, indices, has_initial_state):
    _seq_lens = None
    try:
        _qsl = getattr(attn_metadata, "non_spec_query_start_loc", None)
        if _qsl is not None:
            _seq_lens = [
                int(_x)
                for _x in (_qsl[1:] - _qsl[:-1]).detach().cpu().tolist()
            ]
    except Exception:
        _seq_lens = None
    _his = None
    try:
        if has_initial_state is not None:
            _his = [
                bool(_x) for _x in has_initial_state.detach().cpu().tolist()
            ]
    except Exception:
        _his = None
    _idx = None
    try:
        if indices is not None:
            _idx = [int(_x) for _x in indices.detach().cpu().tolist()]
    except Exception:
        _idx = None
    return {
        "seq": int(_seq),
        "layer": getattr(mod, "prefix", None),
        "num_prefills": int(getattr(attn_metadata, "num_prefills", -1)),
        "seq_lens": _seq_lens,
        "has_initial_state": _his,
        "state_indices": _idx,
    }


def _fr13pct_read(mod, attn_metadata, indices, has_initial_state, initial_state):
    global _fr13pct_seq, _fr13pct_cur_seq, _fr13pct_disabled
    if not _FR13PCT_ON or _fr13pct_disabled:
        return
    try:
        _fr13pct_seq += 1
        _fr13pct_cur_seq = _fr13pct_seq
        _rec = _fr13pct_common(
            _fr13pct_cur_seq, mod, attn_metadata, indices, has_initial_state
        )
        _rec["site"] = "read"
        _rec["read_fp"] = _fr13pct_rowfp(initial_state)
        _fr13pct_emit(_rec)
    except Exception as _exc:
        _fr13pct_disabled = True
        print(
            "FR13_CARRY_TRACE_ERROR read: "
            + type(_exc).__name__ + ": " + str(_exc),
            flush=True,
        )


def _fr13pct_write(mod, attn_metadata, indices, last_recurrent_state):
    global _fr13pct_disabled
    if not _FR13PCT_ON or _fr13pct_disabled:
        return
    try:
        _rec = _fr13pct_common(
            _fr13pct_cur_seq,
            mod,
            attn_metadata,
            indices,
            getattr(attn_metadata, "has_initial_state", None),
        )
        _rec["site"] = "write"
        _rec["write_indices"] = _rec.get("state_indices")
        _rec["written_fp"] = _fr13pct_rowfp(last_recurrent_state)
        _fr13pct_emit(_rec)
    except Exception as _exc:
        _fr13pct_disabled = True
        print(
            "FR13_CARRY_TRACE_ERROR write: "
            + type(_exc).__name__ + ": " + str(_exc),
            flush=True,
        )


if _FR13PCT_ON:
    print(
        "FR13_APC_PREFILL_CARRY_TRACE boot needle: prefill carry tracer ACTIVE "
        "(flag ON at patch time), path=" + _FR13PCT_PATH
        + " limit=" + str(_FR13PCT_LIMIT),
        flush=True,
    )
'''
    text = text.replace(mod_anchor, mod_anchor + mod_block, 1)

    read_anchor = (
        "            initial_state = ssm_state[non_spec_state_indices_tensor]"
        ".contiguous()  # type: ignore[index]\n"
        "            assert has_initial_state is not None\n"
        "            initial_state[~has_initial_state, ...] = 0"
        "  # type: ignore[operator]\n"
    )
    if text.count(read_anchor) != 1:
        raise RuntimeError(
            "carry_trace: gdn_linear read/zero anchor not unique/found"
        )
    read_inject = (
        "            initial_state = ssm_state[non_spec_state_indices_tensor]"
        ".contiguous()  # type: ignore[index]\n"
        "            assert has_initial_state is not None\n"
        "            if _FR13PCT_ON:  " + sentinel + "\n"
        "                _fr13pct_read(\n"
        "                    self,\n"
        "                    attn_metadata,\n"
        "                    non_spec_state_indices_tensor,\n"
        "                    has_initial_state,\n"
        "                    initial_state,\n"
        "                )\n"
        "            initial_state[~has_initial_state, ...] = 0"
        "  # type: ignore[operator]\n"
    )
    text = text.replace(read_anchor, read_inject, 1)

    write_anchor = (
        "            # Init cache\n"
        "            ssm_state[non_spec_state_indices_tensor] = "
        "last_recurrent_state.to(\n"
        "                ssm_state.dtype\n"
        "            )\n"
    )
    if text.count(write_anchor) != 1:
        raise RuntimeError(
            "carry_trace: gdn_linear carry-write anchor not unique/found"
        )
    write_inject = write_anchor + (
        "            if _FR13PCT_ON:  " + sentinel + "\n"
        "                _fr13pct_write(\n"
        "                    self,\n"
        "                    attn_metadata,\n"
        "                    non_spec_state_indices_tensor,\n"
        "                    last_recurrent_state,\n"
        "                )\n"
    )
    text = text.replace(write_anchor, write_inject, 1)

    GDN_LINEAR_PATH.write_text(text)
    return True


def _patch_eagle_dfwd_split_timer() -> bool:
    """FR13_DFWD_SPLIT (default OFF): 3-way GPU split of the tree-drafter cost.

    The dfwd span timer measures the WHOLE propose (~88ms/step at B=4). This
    splits propose_tree's per-level loop into:
      model  -- the draft model forward (CUMULATIVE tokens: query_len grows
                per level, cat8 re-processes 2,4,6,7,8 = 27 token-forwards)
      head   -- compute_logits + topk (full-vocab lm_head weight read/level)
      other  -- everything else (metadata rebuild, repeat/cat, slot math,
                buffer copies, piecewise dispatch) = level_total - model - head
    CUDA-event pairs, async; atexit sidecar (FR13_DFWD_SPLIT_JSON). Decides
    FR-Spec-vocab vs level-fusion vs shape-depth as the drafter attack.
    """
    text = EAGLE_PATH.read_text()
    sentinel = "# FR13_DFWD_SPLIT"
    if sentinel in text:
        return False
    helper = '''

# FR13_DFWD_SPLIT: per-level 3-way drafter timing (default OFF; env FR13_DFWD_SPLIT=1)
class _Fr13DfwdSplit:
    def __init__(self):
        import os as _os
        self.on = _os.environ.get("FR13_DFWD_SPLIT", "0") == "1"
        if not self.on:
            # env-first-then-flag-file: bare FR13_* env may not reach the
            # EngineCore worker (the proven FR13_GDN_SUBOP_MAB pattern); the
            # patcher main() writes the flag inside the container at boot.
            try:
                with open("/logs/fr13_dfwd_split.flag") as _fh:
                    self.on = _fh.read().strip() == "1"
            except Exception:  # noqa: BLE001
                pass
        if self.on:
            try:
                from vllm.logger import init_logger as _il
                _il("vllm.fr13_dfwd_split").info(
                    "FR13_DFWD_SPLIT ENGAGED (worker pid=%s)",
                    __import__("os").getpid(),
                )
            except Exception:  # noqa: BLE001
                pass
        self.pairs = {"model": [], "sample": [], "lmhead": []}
        self.pathmap = set()
        self.done = False
        if self.on:
            import atexit as _ax
            _ax.register(self.dump)

    def begin(self, k):
        if not self.on:
            return None
        import torch as _t
        ev = _t.cuda.Event(enable_timing=True)
        ev.record()
        return ev

    def end(self, k, start_ev):
        if start_ev is None:
            return
        import torch as _t
        ev = _t.cuda.Event(enable_timing=True)
        ev.record()
        self.pairs[k].append((start_ev, ev))
        # periodic dump: teardown is docker rm -f (SIGKILL, no atexit); mirror
        # the span-timer's survival pattern. Level-end only, every 25 levels.
        if k == "model" and len(self.pairs["model"]) % 25 == 0:
            self.done = False
            self.dump()
            self.done = False

    def dump(self):
        if not self.on:
            return
        self.done = True
        import json as _j, os as _os, torch as _t
        try:
            _t.cuda.synchronize()
            out = {"schema": "fr13.dfwd_split.v1"}
            for k, ps in self.pairs.items():
                tot = sum(a.elapsed_time(b) for a, b in ps) / 1000.0
                out[k + "_seconds"] = tot
                out["n_" + k] = len(ps)
            out["other_seconds"] = max(
                0.0, out.get("level_seconds", 0.0)
                - out.get("model_seconds", 0.0) - out.get("head_seconds", 0.0)
            )
            p = _os.environ.get(
                "FR13_DFWD_SPLIT_JSON", "/logs/fr13_dfwd_split.json"
            ) + "." + str(_os.getpid())
            with open(p, "w") as fh:
                _j.dump(out, fh, indent=1)
        except Exception as _e:  # noqa: BLE001
            try:
                import traceback as _tb
                with open("/logs/fr13_dfwd_split.err", "a") as fh:
                    fh.write(repr(_e) + chr(10) + _tb.format_exc() + chr(10))
            except Exception:
                pass


_FR13_DFWD_SPLIT = _Fr13DfwdSplit()

'''
    anchor_cls = "class SpecDecodeBaseProposer:"
    if anchor_cls in text:
        text = text.replace(anchor_cls, helper.lstrip("\n") + "\n" + anchor_cls, 1)
    else:
        raise RuntimeError("FR13_DFWD_SPLIT helper anchor not found")

    # PATH-MAP one-time logs: which drafting path actually runs live.
    def _pm_inject(txt, body_anchor, label):
        idx = txt.index(body_anchor)
        indent = " " * (len(body_anchor) - len(body_anchor.lstrip()))
        inj = (
            indent + "if " + repr(label) + " not in _FR13_DFWD_SPLIT.pathmap:\n"
            + indent + "    _FR13_DFWD_SPLIT.pathmap.add(" + repr(label) + ")\n"
            + indent + "    try:\n"
            + indent + "        from vllm.logger import init_logger as _il\n"
            + indent + "        _il('vllm.fr13_dfwd_split').info('FR13_PATHMAP: %s', " + repr(label) + ")\n"
            + indent + "    except Exception:\n"
            + indent + "        pass\n"
        )
        return txt[:idx] + inj + txt[idx:]

    text = _pm_inject(
        text,
        "        tree_attn_metadata_builder = self.draft_attn_groups[0].get_metadata_builder()",
        "propose_tree ENTERED",
    )
    text = _pm_inject(
        text,
        "            draft_token_ids_list = self.propose_tree(",
        "propose() tree-branch",
    )
    # PARALLEL-DRAFT early exit (the live path per split5 pathmap elimination):
    early = "        if self.num_speculative_tokens == 1 or self.parallel_drafting:\n"
    ei = text.index(early)
    greedy_line = "            draft_token_ids = self._greedy_sample(sample_hidden_states)\n"
    gi = text.index(greedy_line, ei)
    ret_line = text.index("\n", gi + len(greedy_line))
    pm_early = (
        "            if 'propose() PARALLEL early-exit' not in _FR13_DFWD_SPLIT.pathmap:\n"
        "                _FR13_DFWD_SPLIT.pathmap.add('propose() PARALLEL early-exit')\n"
        "                try:\n"
        "                    from vllm.logger import init_logger as _il\n"
        "                    _il('vllm.fr13_dfwd_split').info('FR13_PATHMAP: %s', 'propose() PARALLEL early-exit')\n"
        "                except Exception:\n"
        "                    pass\n"
    )
    text = (
        text[:gi]
        + pm_early
        + "            _fr13_ds_sm = _FR13_DFWD_SPLIT.begin('sample')\n"
        + greedy_line
        + "            _FR13_DFWD_SPLIT.end('sample', _fr13_ds_sm)\n"
        + text[gi + len(greedy_line):]
    )
    # model span: around the ONE draft forward in propose()
    mline = "            ret_hidden_states = self.model(**model_kwargs)\n"
    mi = text.index(mline)
    text = (
        text[:mi]
        + "            _fr13_ds_md = _FR13_DFWD_SPLIT.begin('model')\n"
        + mline
        + "            _FR13_DFWD_SPLIT.end('model', _fr13_ds_md)\n"
        + text[mi + len(mline):]
    )
    EAGLE_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_uniform_dispatch_guard() -> bool:
    """FR13_UNIFORM_DISPATCH_GUARD: veto FULL-cudagraph uniform-decode dispatch on
    PSEUDO-uniform mixed steps (the 2026-07-07 + 2026-07-14 EngineDeadError class).

    Mechanism (workflow wf_c3937df5-d49, 4 mappers converged, verified vs source):
    vLLM's `_is_uniform_decode` is SHAPE-ONLY (max_num_scheduled_tokens ==
    uniform_decode_query_len and num_tokens == max*num_reqs). A chunked-prefill
    TAIL of exactly uniform_decode_query_len (= 1+num_spec, 9 for cat8) tokens
    co-scheduled with tree-spec decodes satisfies both clauses => the runner
    replays the FULL bs=N uniform-SPEC graph: the captured staging fills re-stamp
    flags=[1, N] with capture-time constants while the live step truly has N-1
    spec + 1 prefill, AND the GDN builder's persistent-buffer refresh (gated
    num_prefills==0) was skipped => the whole replayed forward consumes STALE
    spec_state_indices => the committer's rows assert (:9815) fires (correctly).
    SILENT SIBLING: a batch of pure prefill tails each exactly that length (zero
    spec) also replays the spec graph with NO committer to catch it.

    Fix: force_uniform_decode=False (existing kwarg, plumbed to _is_uniform_decode;
    None = stock bit-for-bit) whenever spec decoding is configured AND the step is
    not PURELY spec-decode by the committer's own source of truth
    (scheduled_spec_decode_tokens covering every request, no ndt<0 row). Demoted
    steps dispatch PIECEWISE: the mixed GDN metadata (spec+prefill) is actually
    consumed, the tree staging Python runs live (flags=[1, true_count]), committer
    rows match, and the prefill tail takes the prefill path. `num_spec_tokens > 0`
    guard is LOAD-BEARING: without it, non-spec configs would demote genuine
    1-token uniform decodes and lose FULL graphs. Host-side only, outside any
    captured region; zero HBM/kernel change. NOT flag-gated: the crash class is
    pre-existing (hit 2026-07-07 pre-slot-reorder) and the fix is a pure
    correctness guard.
    """
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_UNIFORM_DISPATCH_GUARD"
    if sentinel in text:
        return False
    anchor = """            ) = self._determine_batch_execution_and_padding(
                num_tokens=num_tokens_unpadded,
                num_reqs=num_reqs,
                num_scheduled_tokens_np=num_scheduled_tokens_np,
                max_num_scheduled_tokens=max_num_scheduled_tokens,
                use_cascade_attn=cascade_attn_prefix_lens is not None,
                num_encoder_reqs=len(scheduler_output.scheduled_encoder_inputs),
            )
"""
    if anchor not in text:
        raise RuntimeError("FR13_UNIFORM_DISPATCH_GUARD anchor not found")
    # The guard must precede the tuple-unpack STATEMENT the anchor closes, so it
    # is injected inside the replacement ahead of a re-emitted assignment; the
    # original assignment's tuple-open lines sit ABOVE the anchor and are left
    # in place -- Python evaluates the RHS call after the guard ran because the
    # guard lines are inserted before the tuple-open via a second anchor below.
    tuple_open = """            (
                cudagraph_mode,
                batch_desc,
                should_ubatch,
                num_tokens_across_dp,
                cudagraph_stats,
            ) = self._determine_batch_execution_and_padding(
"""
    if tuple_open not in text:
        raise RuntimeError("FR13_UNIFORM_DISPATCH_GUARD tuple-open anchor not found")
    guard = """            # FR13_UNIFORM_DISPATCH_GUARD: veto FULL-graph uniform dispatch on
            # pseudo-uniform mixed steps (prefill tail == uniform_decode_query_len
            # co-scheduled with spec decodes => stale-staging graph replay). The
            # purity test is the committer's own source of truth. None = stock.
            _fr13_force_uniform = None
            if self.num_spec_tokens > 0 and (
                len(scheduler_output.scheduled_spec_decode_tokens) != num_reqs
                or bool(
                    (self.num_decode_draft_tokens.np[:num_reqs] < 0).any()
                )
            ):
                _fr13_force_uniform = False
            (
                cudagraph_mode,
                batch_desc,
                should_ubatch,
                num_tokens_across_dp,
                cudagraph_stats,
            ) = self._determine_batch_execution_and_padding(
"""
    text = text.replace(tuple_open, guard, 1)
    new_call = anchor.replace(
        "                num_encoder_reqs=len(scheduler_output.scheduled_encoder_inputs),\n",
        "                num_encoder_reqs=len(scheduler_output.scheduled_encoder_inputs),\n"
        "                force_uniform_decode=_fr13_force_uniform,\n",
    )
    text = text.replace(anchor, new_call, 1)
    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_merged_drafter() -> bool:
    """FR13 merged drafter (MTP-k + Arctic-suffix -> cat33333): drive the Arctic SuffixDecodingCache
    LIFECYCLE (start_request / ingest / retire) at the runner _prepare_inputs frame, where
    self.input_batch (req_ids, token_ids_cpu, num_prompt_tokens, num_computed_tokens_cpu) is in
    scope. Sidecar-gated (fr13_merged_drafter.merged_on() reads /logs/fr13_draft_source_merged.arm,
    worker-env-drop-proof); speculate() + tree-fill happen at the drafter seam. Default (no sidecar)
    = full no-op => byte-identical. Injected AFTER the reqkey block sets _fr13_rk_req_ids; wrapped in
    its OWN try/except so a merged-path error can NEVER disable the (correctness-critical) reqkey
    rewrite or the runner. Must register AFTER _patch_gpu_model_runner_tree_reqkey."""
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_MERGED_DRAFTER_LIFECYCLE"
    if sentinel in text:
        return False
    anchor = "                    _fr13_rk_gdn._LUMO_FA_SAMPLER_ROW_REQ_IDS = _fr13_rk_req_ids\n"
    if anchor not in text:
        raise RuntimeError("FR13 merged-drafter runner anchor (SAMPLER_ROW_REQ_IDS) not found")
    inject = anchor + (
        "                    " + sentinel + ": Arctic lifecycle, sidecar-gated, error-isolated.\n"
        "                    try:\n"
        "                        import sys as _fr13_md_sys\n"
        "                        if \"/workspace/scripts\" not in _fr13_md_sys.path:\n"
        "                            _fr13_md_sys.path.insert(0, \"/workspace/scripts\")\n"
        "                        import fr13_merged_drafter as _fr13_md\n"
        "                        if _fr13_md.merged_on():\n"
        "                            _fr13_md_cache = _fr13_md.get_cache()\n"
        "                            _fr13_md.maybe_prewarm(_fr13_md_cache)\n"
        "                            _fr13_md_new = {}\n"
        "                            for _fr13_md_i, _fr13_md_rid in enumerate(_fr13_rk_req_ids):\n"
        "                                if _fr13_md_cache is not None and _fr13_md_rid not in _fr13_md_cache.active_requests:\n"
        "                                    _fr13_md_np = int(self.input_batch.num_prompt_tokens[_fr13_md_i])\n"
        "                                    _fr13_md_new[_fr13_md_rid] = [int(_x) for _x in self.input_batch.token_ids_cpu[_fr13_md_i, :_fr13_md_np]]\n"
        "                            _fr13_md.note_new_requests(_fr13_md_cache, _fr13_md_new)\n"
        "                            for _fr13_md_i, _fr13_md_rid in enumerate(_fr13_rk_req_ids):\n"
        "                                _fr13_md_nt = int(self.input_batch.num_computed_tokens_cpu[_fr13_md_i])\n"
        "                                _fr13_md.ingest_from_sequence(_fr13_md_cache, _fr13_md_rid, self.input_batch.token_ids_cpu[_fr13_md_i], _fr13_md_nt)\n"
        "                            if _fr13_md_cache is not None:\n"
        "                                _fr13_md_live = set(_fr13_rk_req_ids)\n"
        "                                _fr13_md.retire_requests(_fr13_md_cache, [_fr13_md_r for _fr13_md_r in list(_fr13_md_cache.active_requests) if _fr13_md_r not in _fr13_md_live])\n"
        "                    except Exception:\n"
        "                        pass\n"
    )
    text = text.replace(anchor, inject, 1)
    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_slot_reorder() -> bool:
    """FR13_SLOT_REORDER (edits 1+4 of 5): spine-first canonical KV slot layout.

    Fixes the cat8 accept-rate M-dependence (deep-spine ~1 bf16 ULP from FA2
    butterfly-reduction association keyed by physical score-tile column) by
    permuting WHERE each tree node's K/V lands in the paged cache: physical
    column k holds node pi[k] (pi = spine depth-order, then branches in BFS
    order). The single fused FA2 call then sees the spine at contiguous columns
    0..S-1 IDENTICALLY for cat6/cat8/spine-only => M-invariant by construction,
    context bit-identical (no block-split, no merge, no recompile).

    Three injections into gpu_model_runner.py, all gated on FR13_SLOT_REORDER=1
    (default OFF => byte-identical ship):
      CLEAR   - top of _build_attention_metadata: reset the span stash so a step
                that never reaches propose cannot leak a stale restore.
      PERMUTE - in _build_attn_group_metadata, BEFORE builder.build/update, for
                FULL-ATTENTION builders only (mamba/GDN excluded; their state
                bank is spec_state_indices, a different address space), attn_gid
                ==0 only (metadata for extra attn groups shares the same cm ->
                double-permute hazard), ubid None (no ubatching), skip cudagraph
                capture. In-place on the persistent buffer (pointer-stable for
                FULL cudagraphs). Spec rows identified EXACTLY: span == tree_n
                AND num_decode_draft_tokens == tree_n-1.
      RESTORE - top of propose_draft_token_ids: un-permute the spans BEFORE any
                drafter read (eagle copies common_attn_metadata.slot_mapping
                into its own buffer at eagle.py:469 for the DRAFT model's KV
                writes -- it must see the flat layout). Sampling (and the
                FR13_ATTN_KV_REMAP apply, whose dst-flat fix is edit 3 in
                fr10_gdn_tree_kernel.launch_attn_kv_linear_remap) precedes
                propose, so the permuted map is live exactly for: KV write,
                FA2 verify read, and the remap copy. Stream-ordered.

    Design + hazard log: FR13_CAT6_CAT8_ACCEPT_INVESTIGATION.md (v2). Edit 2
    (bias column permute) + edit 5 (causal=False, provably redundant for the
    decode tree call) live in fr13_patch_fa2_tree_bias.py.
    """
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_SLOT_REORDER_PERMUTE"
    if sentinel in text:
        return False

    clear_anchor = """        assert num_reqs_padded is not None and num_tokens_padded is not None

        attn_metadata: PerLayerAttnMetadata = {}
"""
    clear_inject = """        assert num_reqs_padded is not None and num_tokens_padded is not None

        # FR13_SLOT_REORDER_CLEAR: reset the permuted-span stash at every
        # metadata build so a step that skips propose (exception / no spec)
        # can never leak a stale restore onto freshly recomputed slot values.
        self._fr13_sr_active = {}

        attn_metadata: PerLayerAttnMetadata = {}
"""
    if clear_anchor not in text:
        raise RuntimeError("FR13_SLOT_REORDER clear anchor not found")
    text = text.replace(clear_anchor, clear_inject, 1)

    permute_anchor = """            extra_attn_metadata_args = {}
            if use_spec_decode and isinstance(
"""
    permute_inject = """            # FR13_SLOT_REORDER_PERMUTE: spine-first canonical KV slot layout
            # for the tree-verify suffix (full-attention groups only). See the
            # patch docstring + FR13_CAT6_CAT8_ACCEPT_INVESTIGATION.md.
            if (
                (__import__("os").environ.get("FR13_SLOT_REORDER", "0") == "1"
                 or __import__("os").environ.get("FR13_PB_BASE_COL_INVARIANT", "0") == "1")
                and not for_cudagraph_capture
                and use_spec_decode
                and ubid is None
                and attn_gid == 0
                and not isinstance(
                    builder,
                    (Mamba2AttentionMetadataBuilder, GDNAttentionMetadataBuilder),
                )
            ):
                if __import__("os").environ.get("FR13_ATTN_KV_REMAP", "0") != "1":
                    raise RuntimeError(
                        "FR13_SLOT_REORDER=1 requires FR13_ATTN_KV_REMAP=1 "
                        "(the committer re-linearize owns the dst-flat fix)"
                    )
                _sr_pi = getattr(self, "_fr13_sr_pi_cpu", None)
                if _sr_pi is None:
                    _sr_cfg = __import__("os").environ.get("SPEC_CONFIG")
                    _sr_tree = None
                    if _sr_cfg:
                        _sr_tree = __import__("json").loads(_sr_cfg).get(
                            "speculative_token_tree"
                        )
                    if not _sr_tree:
                        _sr_sc = getattr(self.vllm_config, "speculative_config", None)
                        _sr_tree = getattr(_sr_sc, "speculative_token_tree", None)
                    if not _sr_tree:
                        raise RuntimeError(
                            "FR13_SLOT_REORDER: no speculative_token_tree"
                        )
                    _sr_ch = sorted(
                        __import__("ast").literal_eval(_sr_tree),
                        key=lambda _p: (len(_p), _p),
                    )
                    _sr_is_pb = (
                        __import__("os").environ.get(
                            "FR13_PB_BASE_COL_INVARIANT", "0"
                        ) == "1"
                        and len(_sr_ch) > 8
                        and all(
                            tuple(_sr_ch[_k]) == tuple([0] * (_k + 1))
                            for _k in range(8)
                        )
                    )
                    if _sr_is_pb:
                        # FR13_PB_BASE_COL_INVARIANT: base-first pi (base subtree
                        # nodes 8..tree_n-1 -> phys 0.., dead chain 1-7 + pos-0 ->
                        # tail). MUST match the tree_attn bias _fr13_sr_pi_list
                        # pb branch exactly (both permute the same physical cols).
                        _sr_tn = len(_sr_ch) + 1
                        _sr_pi = (
                            list(range(8, _sr_tn))
                            + list(range(1, 8))
                            + [0]
                        )
                        assert sorted(_sr_pi) == list(range(_sr_tn)), _sr_pi
                    else:
                        _sr_pi = (
                            [0]
                            + [
                                _i + 1
                                for _i, _c in enumerate(_sr_ch)
                                if all(int(_x) == 0 for _x in _c)
                            ]
                            + [
                                _i + 1
                                for _i, _c in enumerate(_sr_ch)
                                if not all(int(_x) == 0 for _x in _c)
                            ]
                        )
                        assert _sr_pi[0] == 0 and sorted(_sr_pi) == list(
                            range(len(_sr_ch) + 1)
                        ), _sr_pi
                    _sr_inv = [0] * len(_sr_pi)
                    for _sr_k, _sr_nd in enumerate(_sr_pi):
                        _sr_inv[_sr_nd] = _sr_k
                    self._fr13_sr_pi_cpu = _sr_pi
                    self._fr13_sr_tree_n = len(_sr_pi)
                    self._fr13_sr_pi_t = torch.tensor(
                        _sr_pi, dtype=torch.long, device=self.device
                    )
                    self._fr13_sr_pi_inv_t = torch.tensor(
                        _sr_inv, dtype=torch.long, device=self.device
                    )
                    logger.info(
                        "FR13_SLOT_REORDER ENGAGED (runner): tree_n=%d pi=%s",
                        self._fr13_sr_tree_n,
                        _sr_pi,
                    )
                _sr_n = self._fr13_sr_tree_n
                _sr_qslc = common_attn_metadata.query_start_loc_cpu
                _sr_ndt = self.num_decode_draft_tokens.cpu
                _sr_sm = common_attn_metadata.slot_mapping
                _sr_spans = []
                for _sr_r in range(int(_sr_qslc.shape[0]) - 1):
                    _sr_q0 = int(_sr_qslc[_sr_r])
                    if (
                        int(_sr_qslc[_sr_r + 1]) - _sr_q0 == _sr_n
                        and _sr_r < int(_sr_ndt.shape[0])
                        and int(_sr_ndt[_sr_r]) == _sr_n - 1
                    ):
                        _sr_sm[_sr_q0 : _sr_q0 + _sr_n] = _sr_sm[
                            _sr_q0 : _sr_q0 + _sr_n
                        ][self._fr13_sr_pi_inv_t]
                        _sr_spans.append(_sr_q0)
                if _sr_spans:
                    if getattr(self, "_fr13_sr_active", None) is None:
                        self._fr13_sr_active = {}
                    self._fr13_sr_active[int(kv_cache_gid)] = (_sr_sm, _sr_spans)
                    self._fr13_sr_steps = getattr(self, "_fr13_sr_steps", 0) + 1

            extra_attn_metadata_args = {}
            if use_spec_decode and isinstance(
"""
    if permute_anchor not in text:
        raise RuntimeError("FR13_SLOT_REORDER permute anchor not found")
    text = text.replace(permute_anchor, permute_inject, 1)

    restore_anchor = """        num_scheduled_tokens = scheduler_output.total_num_scheduled_tokens
        spec_config = self.speculative_config
        assert spec_config is not None
"""
    restore_inject = """        # FR13_SLOT_REORDER_RESTORE: un-permute the verify slot_mapping spans
        # (inverse of FR13_SLOT_REORDER_PERMUTE; sm_perm[pi] == sm_flat) BEFORE
        # any drafter read -- eagle copies common_attn_metadata.slot_mapping
        # into its own buffer (eagle.py:469) for the DRAFT model's KV writes and
        # must see the flat layout. Sampling + FR13_ATTN_KV_REMAP already ran.
        _sr_act = getattr(self, "_fr13_sr_active", None)
        if _sr_act:
            for _sr_sm, _sr_spans in _sr_act.values():
                for _sr_q0 in _sr_spans:
                    _sr_sm[_sr_q0 : _sr_q0 + self._fr13_sr_tree_n] = _sr_sm[
                        _sr_q0 : _sr_q0 + self._fr13_sr_tree_n
                    ][self._fr13_sr_pi_t]
            self._fr13_sr_active = {}
        num_scheduled_tokens = scheduler_output.total_num_scheduled_tokens
        spec_config = self.speculative_config
        assert spec_config is not None
"""
    if restore_anchor not in text:
        raise RuntimeError("FR13_SLOT_REORDER restore anchor not found")
    text = text.replace(restore_anchor, restore_inject, 1)

    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_attn_kv_remap_capture() -> bool:
    """FR13_ATTN_KV_REMAP capture: stash the FULL-ATTENTION kv-cache group's
    per-step slot_mapping + layer names + query_start_loc during the forward's
    attn-metadata build, so the post-commit re-linearize (apply patch, in
    sample_tokens) can move each committed tree node's K/V from its flat verify
    slot to the linear committed slot. Full-attn == a builder that is NOT a
    Mamba2/GDN builder (GDN/mamba bind a tuple kv_cache; full-attn a bare
    tensor). Capture is value-inert (writes only self attributes)."""
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_ATTN_KV_REMAP_CAPTURE"
    if sentinel in text:
        return False
    anchor = (
        "            for layer_name in attn_group.layer_names:\n"
        "                attn_metadata_dict[layer_name] = attn_metadata_i\n"
    )
    if anchor not in text:
        raise RuntimeError("FR13_ATTN_KV_REMAP_CAPTURE anchor not found")
    inject = anchor + (
        f"\n            {sentinel}: full-attn group slot_mapping/layers/qsl for the\n"
        "            # post-commit KV re-linearize. Only under spec decode; only\n"
        "            # non-mamba/GDN builders (= full-attention). Reset the group\n"
        "            # dict on kv_cache_gid==0 so a step's capture never mixes with\n"
        "            # a stale prior step.\n"
        "            if not isinstance(\n"
        "                builder, (Mamba2AttentionMetadataBuilder, GDNAttentionMetadataBuilder)\n"
        "            ):\n"
        "                _fr13_akrc = getattr(self, '_fr13_attn_remap_groups', None)\n"
        "                if _fr13_akrc is None or int(kv_cache_gid) == 0:\n"
        "                    _fr13_akrc = {}\n"
        "                    self._fr13_attn_remap_groups = _fr13_akrc\n"
        "                _fr13_akrc[int(kv_cache_gid)] = (\n"
        "                    common_attn_metadata.slot_mapping,\n"
        "                    list(attn_group.layer_names),\n"
        "                    common_attn_metadata.query_start_loc,\n"
        "                )\n"
    )
    text = text.replace(anchor, inject, 1)
    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def _patch_gpu_model_runner_attn_kv_remap_apply() -> bool:
    """FR13_ATTN_KV_REMAP apply: after the tree committer publishes the accepted
    paths (inside _sample) and BEFORE the drafter / next verify forward, copy
    each committed tree node's full-attn K/V from its flat verify slot to the
    linear committed slot, so the next forward reads the committed-path KV
    instead of a sibling near-neighbor's (the garble carrier). Default OFF
    (FR13_ATTN_KV_REMAP=0): value-inert unless armed. Fail-loud when armed."""
    text = GPU_MODEL_RUNNER_PATH.read_text()
    sentinel = "# FR13_ATTN_KV_REMAP_APPLY"
    if sentinel in text:
        return False
    anchor = (
        "        with record_function_or_nullcontext(\"gpu_model_runner: sample\"):\n"
        "            sampler_output = self._sample(logits, spec_decode_metadata)\n"
    )
    if anchor not in text:
        raise RuntimeError("FR13_ATTN_KV_REMAP_APPLY anchor not found")
    inject = anchor + (
        f"\n        {sentinel}: re-linearize committed-path full-attn KV.\n"
        "        from lumo_flywheel_serving.fr10_gdn_tree_kernel import (\n"
        "            _fr13_piggyback_on as _fr13_akr_pb_probe,\n"
        "        )\n"
        "        if _fr13_akr_pb_probe() and __import__(\"os\").environ.get(\"FR13_ATTN_KV_REMAP\", \"0\") != \"1\":\n"
        "            raise RuntimeError(\n"
        "                \"FR13_PIGGYBACK requires FR13_ATTN_KV_REMAP=1 \"\n"
        "                \"(S1 bonus slot-C copy rides the commit-time remap)\"\n"
        "            )\n"
        "        if __import__(\"os\").environ.get(\"FR13_ATTN_KV_REMAP\", \"0\") == \"1\":\n"
        "            try:\n"
        "                from vllm.model_executor.layers.mamba import gdn_linear_attn as _fr13_akr_gdn\n"
        "                from lumo_flywheel_serving.fr10_gdn_tree_kernel import (\n"
        "                    launch_attn_kv_linear_remap as _fr13_akr_fn,\n"
        "                )\n"
        "                _fr13_akr_groups = getattr(self, \"_fr13_attn_remap_groups\", None)\n"
        "                # FR13_SLOT_REORDER (edit 3/5): under the spine-first slot\n"
        "                # permutation the remap SOURCE auto-threads (reads the same\n"
        "                # permuted slot_mapping) but the DESTINATION must stay the\n"
        "                # FLAT committed slot: dst_pi recovers sm_flat[dst_off] via\n"
        "                # sm_perm[pi[dst_off]]. None when the flag is OFF (shipped\n"
        "                # behavior bit-identical).\n"
        "                _fr13_akr_dstpi = (\n"
        "                    getattr(self, \"_fr13_sr_pi_t\", None)\n"
        "                    if getattr(self, \"_fr13_sr_pi_t\", None) is not None\n"
        "                    else None\n"
        "                )\n"
        "                # FRESH per-step committer paths. The persistent PATHS_TENSOR is\n"
        "                # only refreshed at the NEXT step's pre-forward reqkey (stale\n"
        "                # here), and the *_KERNEL globals live in the committer's OWN\n"
        "                # module namespace (NOT gdn_linear_attn) so they read as None\n"
        "                # here. Read _LUMO_FA_TREE_ACCEPT_BY_REQ (published by THIS step's\n"
        "                # committer ON gdn_linear_attn, keyed by req_id) exactly as the\n"
        "                # reqkey does -> also makes spec-row->path alignment explicit.\n"
        "                # Gate on the FR13_TREE_SAMPLE_ROW freshness counter (reqkey\n"
        "                # zeros at step start; committer sets it) so a commit-less step\n"
        "                # never remaps on a stale path.\n"
        "                _fr13_akr_nrows = int(getattr(_fr13_akr_gdn, \"_LUMO_FA_TREE_COMMIT_NROWS\", 0) or 0)\n"
        "                _fr13_akr_by_req = getattr(_fr13_akr_gdn, \"_LUMO_FA_TREE_ACCEPT_BY_REQ\", None)\n"
        "                _fr13_akr_rids = getattr(_fr13_akr_gdn, \"_LUMO_FA_SPEC_ROW_REQ_IDS\", None)\n"
        "                _fr13_akr_n = len(_fr13_akr_rids) if _fr13_akr_rids else 0\n"
        "                _fr13_akr_rows = []\n"
        "                if _fr13_akr_by_req and _fr13_akr_n > 0:\n"
        "                    for _fr13_akr_rid in _fr13_akr_rids:\n"
        "                        _fr13_akr_e = _fr13_akr_by_req.get(str(_fr13_akr_rid))\n"
        "                        _fr13_akr_rows.append(\n"
        "                            ([int(_x) for _x in _fr13_akr_e[0]], int(_fr13_akr_e[1]))\n"
        "                            if _fr13_akr_e is not None else ([], 0)\n"
        "                        )\n"
        "                # FR13_PIGGYBACK invariant guard: under the extended cat9_pb\n"
        "                # tree the committer walks from rank 7 ((0,)^8) and publishes\n"
        "                # +1-shifted SUBTREE flat rows only (>= 9). A chain row (1..8)\n"
        "                # or root copy (0) here would remap garbage scratch KV onto a\n"
        "                # committed slot. Fail loud (bug-class 9).\n"
        "                if _fr13_akr_rows:\n"
        "                    from lumo_flywheel_serving.fr10_gdn_tree_kernel import (\n"
        "                        _fr13_piggyback_on as _fr13_akr_pb_on,\n"
        "                    )\n"
        "                    if _fr13_akr_pb_on():\n"
        "                        for _fr13_akr_r in _fr13_akr_rows:\n"
        "                            if any(int(_fr13_akr_x) < 9 for _fr13_akr_x in _fr13_akr_r[0][: _fr13_akr_r[1]]):\n"
        "                                raise RuntimeError(\n"
        "                                    \"FR13_PIGGYBACK: accepted path contains a \"\n"
        "                                    \"chain/root flat row (<9): \"\n"
        "                                    + str(_fr13_akr_r[0][: _fr13_akr_r[1]])\n"
        "                                )\n"
        "                if __import__(\"os\").environ.get(\"FR13_BRANCH_ACCEPT_DIAG\", \"0\") == \"1\":\n"
        "                    # FR13_BRANCH_ACCEPT_DIAG (diagnostic, default OFF): per-flat-verify-row\n"
        "                    # accept histogram, accumulated ONCE per step here (single chokepoint).\n"
        "                    # Offline classifies each flat row spine-vs-branch (from the tree) ->\n"
        "                    # branch-rescue rate = branch-row accepts / total. Value-inert unless armed.\n"
        "                    try:\n"
        "                        _fr13_bah = getattr(_fr13_akr_gdn, \"_LUMO_BRANCH_ACCEPT_HIST\", None)\n"
        "                        if _fr13_bah is None:\n"
        "                            _fr13_bah = {\"rows\": {}, \"events\": 0, \"committed\": 0, \"steps\": 0}\n"
        "                            _fr13_akr_gdn._LUMO_BRANCH_ACCEPT_HIST = _fr13_bah\n"
        "                        _fr13_bah[\"steps\"] += 1\n"
        "                        for _fr13_brw in _fr13_akr_rows:\n"
        "                            _fr13_bah[\"events\"] += 1\n"
        "                            for _fr13_bxx in _fr13_brw[0][: _fr13_brw[1]]:\n"
        "                                _fr13_bah[\"committed\"] += 1\n"
        "                                _fr13_bkk = str(int(_fr13_bxx))\n"
        "                                _fr13_bah[\"rows\"][_fr13_bkk] = _fr13_bah[\"rows\"].get(_fr13_bkk, 0) + 1\n"
        "                        _fr13_bjp = __import__(\"os\").environ.get(\"FR13_BRANCH_ACCEPT_JSON\")\n"
        "                        if _fr13_bjp and _fr13_bah[\"steps\"] % 20 == 0:\n"
        "                            import json as _fr13_bjm\n"
        "                            _fr13_btmp = _fr13_bjp + \".tmp\"\n"
        "                            with open(_fr13_btmp, \"w\") as _fr13_bfh:\n"
        "                                _fr13_bjm.dump(_fr13_bah, _fr13_bfh)\n"
        "                            __import__(\"os\").replace(_fr13_btmp, _fr13_bjp)\n"
        "                    except Exception:\n"
        "                        pass\n"
        "                _fr13_akr_pb = _fr13_akr_pb_probe()\n"
        "                _fr13_akr_cols = max((len(_r[0]) for _r in _fr13_akr_rows), default=0)\n"
        "                if _fr13_akr_pb and _fr13_akr_n > 0 and _fr13_akr_nrows > 0:\n"
        "                    # S1(a): the bonus copy must fire on ALL-zero-accept\n"
        "                    # steps too; force the paths tensor to build (padded\n"
        "                    # zeros, lens 0 -> no foreign copies, bonus pair only).\n"
        "                    _fr13_akr_cols = max(_fr13_akr_cols, 1)\n"
        "                _fr13_akr_paths = None\n"
        "                _fr13_akr_lens = None\n"
        "                if (\n"
        "                    _fr13_akr_groups\n"
        "                    and _fr13_akr_n > 0\n"
        "                    and _fr13_akr_nrows > 0\n"
        "                    and _fr13_akr_cols > 0\n"
        "                ):\n"
        "                    _fr13_akr_dev = next(iter(_fr13_akr_groups.values()))[0].device\n"
        "                    _fr13_akr_paths = torch.tensor(\n"
        "                        [\n"
        "                            _r[0] + [0] * (_fr13_akr_cols - len(_r[0]))\n"
        "                            for _r in _fr13_akr_rows\n"
        "                        ],\n"
        "                        dtype=torch.long, device=_fr13_akr_dev,\n"
        "                    )\n"
        "                    _fr13_akr_lens = torch.tensor(\n"
        "                        [_r[1] for _r in _fr13_akr_rows],\n"
        "                        dtype=torch.long, device=_fr13_akr_dev,\n"
        "                    )\n"
        "                if (\n"
        "                    _fr13_akr_paths is not None\n"
        "                    and _fr13_akr_lens is not None\n"
        "                    and _fr13_akr_groups\n"
        "                    and _fr13_akr_n > 0\n"
        "                ):\n"
        "                    _fr13_akr_fwd = (\n"
        "                        self.vllm_config.compilation_config.static_forward_context\n"
        "                    )\n"
        "                    _fr13_akr_tot = 0\n"
        "                    for _fr13_akr_sm, _fr13_akr_lyrs, _fr13_akr_qsl in _fr13_akr_groups.values():\n"
        "                        _fr13_akr_kvs = []\n"
        "                        for _fr13_akr_ln in _fr13_akr_lyrs:\n"
        "                            _fr13_akr_mod = _fr13_akr_fwd.get(_fr13_akr_ln)\n"
        "                            _fr13_akr_kv = (\n"
        "                                getattr(_fr13_akr_mod, \"kv_cache\", None)\n"
        "                                if _fr13_akr_mod is not None else None\n"
        "                            )\n"
        "                            if (\n"
        "                                torch.is_tensor(_fr13_akr_kv)\n"
        "                                and _fr13_akr_kv.numel() > 0\n"
        "                                and int(_fr13_akr_kv.shape[0]) == 2\n"
        "                            ):\n"
        "                                _fr13_akr_kvs.append(_fr13_akr_kv)\n"
        "                        if _fr13_akr_kvs:\n"
        "                            _fr13_akr_tot += _fr13_akr_fn(\n"
        "                                kv_caches=_fr13_akr_kvs,\n"
        "                                slot_mapping=_fr13_akr_sm,\n"
        "                                query_start_loc=_fr13_akr_qsl,\n"
        "                                accepted_paths=_fr13_akr_paths,\n"
        "                                num_accepted_tokens=_fr13_akr_lens,\n"
        "                                num_spec_decodes=_fr13_akr_n,\n"
        "                                dst_pi=_fr13_akr_dstpi,\n"
        "                                pb_bonus_src=(8 if _fr13_akr_pb else None),\n"
        "                            )\n"
        "                    _fr13_akr_seen = getattr(self, \"_fr13_akr_foreign_seen\", 0)\n"
        "                    self._fr13_akr_foreign_seen = _fr13_akr_seen + _fr13_akr_tot\n"
        "                    if not getattr(self, \"_fr13_akr_announced\", False):\n"
        "                        self._fr13_akr_announced = True\n"
        "                        logger.info(\n"
        "                            \"FR13_ATTN_KV_REMAP ENGAGED: groups=%d spec_rows=%d foreign_first=%d path0=%s len0=%s (flat rows start at 1; spine=[1,2,4,6,8] foreign=3)\",\n"
        "                            len(_fr13_akr_groups), _fr13_akr_n, _fr13_akr_tot,\n"
        "                            _fr13_akr_rows[0][0][:6] if _fr13_akr_rows else None,\n"
        "                            _fr13_akr_rows[0][1] if _fr13_akr_rows else None,\n"
        "                        )\n"
        "            except Exception as _fr13_akr_exc:\n"
        "                raise RuntimeError(\n"
        "                    \"FR13_ATTN_KV_REMAP failed: \"\n"
        "                    + type(_fr13_akr_exc).__name__ + \":\" + str(_fr13_akr_exc)\n"
        "                ) from _fr13_akr_exc\n"
    )
    text = text.replace(anchor, inject, 1)
    GPU_MODEL_RUNNER_PATH.write_text(text)
    return True


def main() -> int:
    _fr13_write_subop_mab_sidecar()
    try:
        with open('/logs/fr13_dfwd_split.flag', 'w') as _fh:
            _fh.write(os.environ.get('FR13_DFWD_SPLIT', '0'))
    except Exception:
        pass
    _fr13_write_conv_subop_mab_sidecar()
    _fr13_write_replay_durable_ab_sidecar()
    _fr13_write_apc_env_sidecar()
    patch_steps = [
        (REQUEST_PATH, _patch_request_decode_mode()),
        (SCHED_OUTPUT_PATH, _patch_sched_output_decode_mode()),
        (SCHEDULER_PATH, _patch_scheduler_decode_modes()),
        (GDN_ATTN_PATH, _patch_gdn_attn()),
        (GDN_LINEAR_PATH, _patch_gdn_linear()),
        (SCHEDULER_PATH, _patch_scheduler_spec_trace()),
        (SCHEDULER_PATH, _patch_scheduler_fr13_freereq_cleanup()),
        (SCHEDULER_PATH, _patch_scheduler_mamba_block_align_45477()),
        (EAGLE_PATH, _patch_eagle_tree_consumption_verify()),
        (EAGLE_PATH, _patch_eagle_mtp_draft_trace()),
        (EAGLE_PATH, _patch_eagle_dfwd_split_timer()),
        (TREE_ATTN_PATH, _patch_tree_attn_spec_config_override()),
        (TRITON_UNIFIED_ATTN_PATH, _patch_triton_unified_attention_fr13()),
        (TREE_ATTN_PATH, _patch_tree_attn_op_capture()),
        (FLASH_ATTN_PATH, _patch_flash_attn_op_capture()),
        (QWEN3_NEXT_PATH, _patch_qwen_root_hidden_capture()),
        (QWEN3_NEXT_PATH, _patch_qwen_full_attn_capture()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_tree_metadata()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_tree_depth_positions()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_preprocess_input_capture()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_tree_verify_input_ids()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_pb_input_range_guard()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_draft_handoff_trim()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_row_req_ids_fresh()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_decode_mode_globals()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_tree_reqkey()),
        # FR13_MERGED_DRAFTER: Arctic SuffixDecodingCache lifecycle at the runner,
        # sidecar-gated (no-op unless FR13_DRAFT_SOURCE=merged). MUST run AFTER
        # tree_reqkey (anchors on its _fr13_rk_req_ids line).
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_merged_drafter()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_attn_kv_remap_capture()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_attn_kv_remap_apply()),
        # FR13_SLOT_REORDER (edits 1+4/5): spine-first canonical KV slot layout,
        # default OFF. Must run AFTER remap_apply (whose _sample anchor precedes
        # this patch's propose_draft_token_ids restore anchor in program order,
        # but the two injections share no anchor text -- order-independent).
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_slot_reorder()),
        # FR13_UNIFORM_DISPATCH_GUARD: pre-existing pseudo-uniform mixed-step
        # graph-replay crash fix (NOT flag-gated; pure correctness guard).
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_uniform_dispatch_guard()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_replay_draft_reqkey()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_fr13_det_warn()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_replay_boundary_tap_d()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_sfwd_gpu_timer()),
        # FR13_CFWD_GPU_TIMER: committer span begin/end around the rejection-
        # sampler dispatch in _sample (CALLER level; the sampler twin regions
        # are owned by another workstream). Must run AFTER the sfwd timer
        # patch, whose module block defines the _fr13_cfwd_* helpers.
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_cfwd_gpu_timer()),
        (MAMBA_UTILS_PATH, _patch_mamba_utils_tree_accept_bias()),
        (MAMBA_UTILS_PATH, _patch_mamba_utils_boundary_log()),
        (MAMBA_UTILS_PATH, _patch_mamba_utils_preprocess_context_flag()),
        # Stamps the postprocess_mamba idempotency sentinel (the commit-site
        # write-through it once emitted is removed; byte-identical to stock).
        (MAMBA_UTILS_PATH, _patch_mamba_utils_apc_align_tree_aware()),
        # FR13_APC_SNAP_FIX: redirect the postprocess SSM snapshot copy SOURCE to
        # the committed-leaf node-bank row (the deployment lossless fix). Default
        # OFF => byte-identical. Must run AFTER the accept-bias patch (its offset++
        # anchor is unconsumed by it).
        (MAMBA_UTILS_PATH, _patch_worker_mamba_snap_fidelity()),
        (MAMBA_STATE_UTILS_PATH, _patch_mamba_state_utils_tree_conv_node_copy()),
        (REJECTION_SAMPLER_PATH, _patch_rejection_sampler_tree_lcp()),
        (FP8_UTILS_PATH, _patch_fp8_utils_gb10_gemv_cfg()),
        # FR13_APC_ZERO_MAMBA_ON_ALLOC (default OFF / PATCH-TIME gated ->
        # byte-identical source when the env flag is not "1" at patch time).
        # Zeros recycled GDN conv/ssm state-pool rows on (re)allocation so
        # request N-1 residual can't leak into request N's cold prefill /
        # tree node-bank reads (campaign sec.47/48 request-order carrier).
        (SINGLE_TYPE_MANAGER_PATH, _patch_single_type_manager_zero_mamba()),
        (GPU_MODEL_RUNNER_PATH, _patch_gpu_model_runner_zero_mamba()),
        # FR13_APC_PREFILL_CARRY_TRACE (D-E4CAP; default OFF / PATCH-TIME gated
        # -> byte-identical source when the env flag is not "1"). READ-ONLY
        # tracer of the chunked-prefill SSM carry read/zero/write to localize
        # the residual deterministic cold-path carrier (campaign sec.51). MUST
        # run after _patch_gdn_linear so its anchors match the post-patch text.
        (GDN_LINEAR_PATH, _patch_gdn_linear_attn_prefill_carry_trace()),
    ]
    patched: dict[str, bool] = {}
    for path, did_patch in patch_steps:
        patched[str(path)] = patched.get(str(path), False) or did_patch
    if patched.get(str(QWEN3_NEXT_PATH), False):
        patched[str(QWEN3_5_PATH)] = True
    import py_compile

    for path, did_patch in patched.items():
        if did_patch:
            py_compile.compile(path, doraise=True)
    print(patched)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
